      "card_ids": ["C19"],
      "claim": "Ofloxacin has absolute oral bioavailability greater than 95% in healthy subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Minocycline, a complex polycyclic antibiotic, has oral bioavailability of 90-100%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Ketanserin has absolute oral bioavailability of 46.8±8.2% in healthy subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "Meperidine/pethidine has oral bioavailability of approximately 45-63% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Rifapentine has 70% absolute oral bioavailability in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Encainide has mean absolute oral bioavailability of 32±7% in normal subjects, above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues support oral bioavailability at or above 20%, with the structurally relevant vinorelbine at ~33-43% and the indolocarbazole analogue predicted >30%. No affirmative threshold-relevant evidence supports F<20%, so the query is predicted high.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement exists for the query molecule itself.",
    "The LCS1269 record is a computational HIA prediction rather than a measured absolute bioavailability value.",
    "Some qualitative 'low' or 'poor' bioavailability reports (e.g., encainide C14, pethidine C46, ketanserin C30 range) do not confirm F<20% and were not treated as affirmative low evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

